 range(){let start=date(this.selected),end;if(this.config.summary){start=new Date();end=add(start,30);}else if(this.mode==='month'){start=new Date(this.anchor.getFullYear(),this.anchor.getMonth(),1);start=add(start,-((start.getDay()+6)%7));end=add(start,42);}else if(this.mode==='week'){start=add(start,-((start.getDay()+6)%7));end=add(start,7);}else if(this.mode==='day'){end=add(start,1);}else{start=new Date(this.anchor.getFullYear(),this.anchor.getMonth(),1);end=new Date(this.anchor.getFullYear(),this.anchor.getMonth()+1,1);}return {start,end};}
