 if(this.c.collapsible){html='<button class="fold" data-toggle aria-expanded="'+!!this.open+'"><div><small class="eyebrow">'+esc(this.c.eyebrow||'HOME LAB')+'</small><h3>'+esc(this.c.title)+'</h3></div><span class="chevron">'+(this.open?'−':'+')+'</span></button><div class="status '+(faults.length||missing.length?'warn':'')+'"><span class="dot"></span>'+esc(status)+'</div><div class="shortcuts">'+(this.c.shortcuts||[]).map(s=>'<button data-shortcut="'+esc(s.key)+'" class="'+(this.open&&this.section===s.key?'selected':'')+'"><ha-icon icon="'+esc(s.icon)+'"></ha-icon>'+esc(s.name)+'</button>').join('')+'</div>';const alerts=[...faults,...missing].filter(m=>m.alert!==false);if(alerts.length)html+='<div class="alerts">'+alerts.map(m=>'<button data-entity="'+esc(m.entity)+'"><span class="dot"></span>'+esc(m.name)+'<small>'+esc(this.value(m))+'</small></button>').join('')+'</div>';html+='<div class="fold-body" '+(!this.open?'hidden':'')+'>';if(this.open&&(!this.section||this.section==='server'))html+='<div class="metrics">'+this.c.highlights.map(m=>this.tile(m)).join('')+'</div>';}
 if(this.c.mode==='overview'&&!this.c.collapsible){html+='<div class="status '+(faults.length||missing.length?'warn':'')+'"><span class="dot"></span>'+esc(status)+'</div><div class="metrics">'+this.c.highlights.map(m=>this.tile(m)).join('')+'</div>';}
 html+=(this.c.groups||[]).filter(g=>(!this.c.collapsible||this.open&&(!this.section||g.key===this.section))&&(!g.only_issues||g.metrics.some(m=>this.fault(m)||!this.valid(m.entity)))).map(g=>'<section><div class="section-title">'+esc(g.name)+'</div>'+(g.style==='rings'?'<div class="rings">'+g.metrics.map(m=>this.ring(m)).join('')+'</div>':g.style==='pills'?'<div class="pills">'+g.metrics.filter(m=>!g.only_issues||this.fault(m)||!this.valid(m.entity)).map(m=>'<button class="pill '+(this.fault(m)?'warn':!this.valid(m.entity)?'missing':'')+'" data-entity="'+esc(m.entity)+'"><span class="dot"></span><span>'+esc(m.name)+'</span><small>'+esc(this.value(m))+'</small></button>').join('')+'</div>':g.style==='meters'?'<div class="meters">'+g.metrics.map(m=>{const n=Number(this.h.states[m.entity]?.state),valid=this.valid(m.entity),a=this.h.states[m.entity]?.attributes;return '<button class="meter '+(this.fault(m)?'warn':'')+'" data-entity="'+esc(m.entity)+'"><div><span>'+esc(m.name)+'</span><b>'+esc(this.value(m))+'</b></div><div class="track"><i style="width:'+(valid&&Number.isFinite(n)?Math.max(0,Math.min(100,n)):0)+'%"></i></div>'+(a?.free?'<small>'+esc(a.free)+' free'+(Number.isFinite(a.temperature_celsius)?' · '+esc(a.temperature_celsius)+' °C':'')+'</small>':'')+'</button>';}).join('')+'</div>':'<div class="metrics">'+g.metrics.map(m=>this.tile(m)).join('')+'</div>')+'</section>').join('');
 if(this.c.uptime&&this.valid(this.c.uptime)){const t=Date.parse(this.h.states[this.c.uptime].state);if(Number.isFinite(t))html+='<footer>Server online since '+esc(new Date(t).toLocaleDateString('en-IE',{day:'numeric',month:'short'}))+'</footer>';}
