 num(key,kind){const s=this.state(key);if(!s||['unknown','unavailable','none',''].includes(s.state))return null;const n=Number(s.state);if(!Number.isFinite(n))return null;const u=s.attributes.unit_of_measurement;if(kind==='power')return u==='kW'?n:u==='W'?n/1000:u==='MW'?n*1000:null;if(kind==='energy')return u==='kWh'?n:u==='Wh'?n/1000:u==='MWh'?n*1000:null;return n;}
