function timestamp(state){if(!state)return null;const n=Number(state.attributes?.timestamp);if(n>0)return n*1000;const date=Date.parse(String(state.state).replace(' ','T'));return Number.isFinite(date)?date:null;}
function durationText(minutes){if(minutes===null||!Number.isFinite(minutes)||minutes<0)return'Unavailable';const m=Math.floor(minutes);return String(Math.floor(m/60)).padStart(2,'0')+':'+String(m%60).padStart(2,'0');}
function durationMinutes(h,id,fallbackUnit='min'){const n=numeric(h,id);if(n===null||n<0)return null;const unit=reading(h,id)?.attributes?.unit_of_measurement||fallbackUnit;return['s','sec','seconds'].includes(unit)?n/60:['min','minutes'].includes(unit)?n:['h','hours'].includes(unit)?n*60:null;}
function applianceValues(h,c,a,demoSwitches,now=Date.now()){
 const demo=isDemo(c,a.entities),ids=a.entities||{},p=demo?(a.kind==='washer'?.38:a.kind==='dryer'?1.6:a.kind==='dishwasher'?.9:a.kind==='kettle'?2.1:.08):power(h,ids.power),run=reading(h,ids.running),state=run?.state?.toLowerCase(),active=demo?(demoSwitches?.get('appliance:'+a.id)??true):ids.running?(a.running_states||['on','run','running','washing','drying','playing']).map(x=>String(x).toLowerCase()).includes(state):p!==null&&p*1000>(a.running_threshold_w??5),known=demo||(ids.running?!!run:p!==null);
 const start=timestamp(reading(h,ids.started_at)),elapsed=demo&&active?'00:42':active&&start!==null&&start<=now?durationText((now-start)/60000):'';
 const names={ready:'Ready',inactive:'Off',delayedstart:'Scheduled',pause:'Paused',paused:'Paused',actionrequired:'Needs attention',finished:'Finished',error:'Error',aborting:'Stopping'},status=!known?'Status unavailable':active?({washer:'Washing',dryer:'Drying',dishwasher:'Washing dishes',kettle:'Boiling',extractor:'Ventilating',tv:'Playing',pc:'Running',desk:'In use'}[a.kind]||'Running'):names[state]||'Idle';
 const finish=demo&&a.kind==='dishwasher'?now+38*60000:timestamp(reading(h,ids.finishes_at)),rawProgress=demo&&a.kind==='dishwasher'?64:numeric(h,ids.progress),progress=rawProgress===null?null:Math.max(0,Math.min(100,rawProgress)),remaining=demo&&a.kind==='dishwasher'?38:ids.remaining_time?durationMinutes(h,ids.remaining_time,a.duration_unit||'min'):finish!==null&&finish>=now?(finish-now)/60000:null;
 const door=demo&&a.kind==='dishwasher'?'Closed':reading(h,ids.door)?.state,doorLabel=['on','open','opened'].includes(door?.toLowerCase())?'Open':['off','closed','close'].includes(door?.toLowerCase())?'Closed':door||null;
 return{demo,power:p,active,known,elapsed,status,progress,finish,remaining,door:doorLabel,programme:demo&&a.kind==='dishwasher'?'Eco':reading(h,ids.programme)?.state||null,daily:demo?1.4:energy(h,ids.daily_energy),monthly:demo?12.3:energy(h,ids.monthly_energy),lastDuration:demo?84:durationMinutes(h,ids.last_duration,a.duration_unit||'min'),lastEnergy:demo?0.74:energy(h,ids.last_energy),cycleEnergy:demo?0.32:energy(h,ids.cycle_energy)};
}

