 const demo=this.demo(Object.fromEntries(items.flatMap(x=>Object.entries(x.entities||{}).map(([k,v])=>[x.id+'_'+k,v])))),states={...this._hass.states};
 const entity=(kind,key,value,unit='',name=key)=>{const item=items.find(x=>x.kind===kind),id=item?.entities[key];if(!demo)return id||'';const fake='sensor.demo_lab_'+kind+'_'+key;states[fake]={state:String(value),attributes:{unit_of_measurement:unit,friendly_name:name}};return fake;};
 const metric=(name,kind,key,value,unit='',extra={})=>({name,entity:entity(kind,key,value,unit,name),...extra});
